<?php require_once __DIR__.'/functions.php'; if(!logged())redirect('login.php');$s=db()->prepare('SELECT b.*,r.name room_name FROM bookings b JOIN rooms r ON r.id=b.room_id WHERE b.user_id=? ORDER BY b.created_at DESC');$s->execute([$_SESSION['user']['id']]);$rows=$s->fetchAll();header_html('My Bookings');?><main class="container py-5"><h1 class="display-6 fw-bold">My bookings</h1><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Room</th><th>Dates</th><th>Guests</th><th>Total</th><th>Status</th><th>Payment</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['room_name'])?></td><td><?=e($r['check_in'])?> → <?=e($r['check_out'])?></td><td><?=e($r['guests'])?></td><td>TZS <?=number_format($r['total'])?></td><td><span class="badge text-bg-secondary"><?=e($r['status'])?></span></td><td><?=e($r['payment_status'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center py-5">No bookings yet. <a href="booking.php">Make your first booking</a></td></tr><?php endif;?></tbody></table></div></main><?php footer_html();?>